const entrada = $input.all().map(i => i.json);
const falhou = entrada.find(l => l.error);

// ?periodo=7d mostra a semana; o resto, as últimas 24 h
const consulta = $('Abre o painel').first().json.query ?? {};
const período = consulta.periodo === '7d' ? '7d' : '24h';
const janela = (período === '7d' ? 7 * 24 : 24) * 60 * 60 * 1000;

const agora = Date.now();
const todas = entrada
  .filter(l => l.coletado_em)
  .map(l => ({ ...l, quando: new Date(l.coletado_em).getTime() }))
  .sort((a, b) => a.quando - b.quando);
const linhas = todas.filter(l => agora - l.quando <= janela);
const última = todas.at(-1);
const primeira = linhas[0];

const fuso = { timeZone: 'America/Sao_Paulo' };
const hora = quando => new Date(quando).toLocaleTimeString('pt-BR', { ...fuso, hour: '2-digit', minute: '2-digit' });
const diaEHora = quando => new Date(quando).toLocaleString('pt-BR', { ...fuso, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const rótulo = período === '7d' ? diaEHora : hora;

// o selo do topo: o fluxo de stats coleta a cada 15 minutos, então 20 sem nada já é sinal
const idadeMin = última ? Math.round((agora - última.quando) / 60000) : null;
const selo = !última
  ? { classe: 'neutro', texto: 'Sem dados ainda' }
  : idadeMin <= 20
    ? { classe: 'ok', texto: 'Coletando' }
    : { classe: 'alerta', texto: idadeMin < 120 ? `Sem coleta há ${idadeMin} min` : `Sem coleta há ${Math.round(idadeMin / 60)} h` };

const número = valor => (valor ?? 0).toLocaleString('pt-BR', { maximumFractionDigits: 0 });

// cada cartão: o valor de agora e quanto mudou desde o começo do período. Verde sobe e
// vermelho desce só onde subir é bom; memória mudando não é nem uma coisa nem outra
const cartão = (título, campo, { sufixo = '', semCor = false } = {}) => {
  if (!última) return { título, valor: '—', variação: '', tendência: 'neutro' };

  const diferença = primeira ? (última[campo] ?? 0) - (primeira[campo] ?? 0) : 0;
  const tendência = semCor || diferença === 0 ? 'neutro' : diferença > 0 ? 'sobe' : 'desce';
  const quanto = período === '7d' ? '7 dias' : '24 h';
  const variação = diferença === 0
    ? `estável em ${quanto}`
    : `${diferença > 0 ? '+' : '−'}${número(Math.abs(diferença))}${sufixo} em ${quanto}`;

  return { título, valor: número(última[campo]) + sufixo, variação, tendência };
};

const cartões = [
  cartão('Servidores', 'servidores'),
  cartão('Membros', 'membros'),
  cartão('Online agora', 'online'),
  cartão('Tocando agora', 'tocando'),
  cartão('Memória', 'memoria_mb', { sufixo: ' MB', semCor: true }),
];

const cores = { roxo: '#af87ff', verde: '#23a55a', azul: '#00a8fc', laranja: '#ffaf00', rosa: '#eb459e' };

const gráficos = [
  { título: 'Membros e pessoas online', inteiros: true, séries: [['membros', 'Membros', cores.roxo], ['online', 'Online', cores.verde]] },
  { título: 'Música', inteiros: true, séries: [['players', 'Players', cores.roxo], ['tocando', 'Tocando', cores.verde], ['na_fila', 'Na fila', cores.laranja]] },
  { título: 'Memória (MB)', inteiros: false, séries: [['memoria_mb', 'Processo', cores.azul], ['heap_mb', 'Heap do .NET', cores.rosa]] },
  { título: 'Servidores', inteiros: true, degrau: true, séries: [['servidores', 'Servidores', cores.roxo]] },
].map(g => ({
  ...g,
  séries: g.séries.map(([campo, nome, cor]) => ({ nome, cor, valores: linhas.map(l => l[campo] ?? null) })),
}));

// o JSON vai dentro de um <script>: sem "<" cru, nada dele fecha a tag antes da hora
const dados = JSON.stringify({ rótulos: linhas.map(l => rótulo(l.quando)), gráficos })
  .replace(/</g, '\\u003c');

const aviso = falhou
  ? 'A tabela <code>aleph_stats</code> ainda não existe: ela nasce na primeira rodada do fluxo "AlephBot · Histórico de stats".'
  : linhas.length === 0
    ? 'Ainda não tem histórico neste período: o fluxo "AlephBot · Histórico de stats" grava uma coleta a cada 15 minutos.'
    : '';

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="300">
<title>AlephBot · Painel</title>
<style>
  :root {
    --fundo: #1e1f22;
    --cartao: #2b2d31;
    --borda: #3f4147;
    --texto: #f2f3f5;
    --apagado: #949ba4;
    --roxo: ${cores.roxo};
    --verde: ${cores.verde};
    --laranja: ${cores.laranja};
    --vermelho: #f23f43;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: var(--fundo);
    color: var(--texto);
    font-family: "gg sans", "Segoe UI", system-ui, sans-serif;
  }
  main { max-width: 1200px; margin: 0 auto; padding: 32px 24px 48px; }
  header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 24px; }
  .marca { display: flex; align-items: center; gap: 14px; }
  .avatar {
    width: 48px; height: 48px; border-radius: 50%;
    display: grid; place-items: center;
    background: linear-gradient(135deg, var(--roxo), #7c4dff);
    font-weight: 800; font-size: 22px; color: #fff;
  }
  h1 { margin: 0; font-size: 22px; }
  .sub { margin: 2px 0 0; color: var(--apagado); font-size: 14px; }
  .acoes { display: flex; align-items: center; gap: 12px; }
  .selo { display: inline-flex; align-items: center; gap: 8px; padding: 6px 12px; border-radius: 999px; background: var(--cartao); font-size: 13px; font-weight: 600; }
  .selo::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--apagado); }
  .selo.ok::before { background: var(--verde); box-shadow: 0 0 0 4px rgba(35, 165, 90, .2); }
  .selo.alerta::before { background: var(--laranja); }
  .periodo { display: inline-flex; padding: 3px; border-radius: 8px; background: var(--cartao); }
  .periodo a { padding: 6px 14px; border-radius: 6px; color: var(--apagado); text-decoration: none; font-size: 13px; font-weight: 600; }
  .periodo a.atual { background: var(--borda); color: var(--texto); }
  .aviso { padding: 14px 16px; border-radius: 8px; background: var(--cartao); border-left: 4px solid var(--laranja); color: var(--texto); }
  .cartoes { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 16px; margin-bottom: 16px; }
  .cartao { padding: 18px 20px; border-radius: 12px; background: var(--cartao); }
  .cartao .titulo { color: var(--apagado); font-size: 12px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
  .cartao .valor { margin-top: 8px; font-size: 30px; font-weight: 800; }
  .cartao .variacao { margin-top: 4px; font-size: 13px; color: var(--apagado); }
  .cartao .variacao.sobe { color: var(--verde); }
  .cartao .variacao.desce { color: var(--vermelho); }
  .graficos { display: grid; grid-template-columns: repeat(auto-fit, minmax(460px, 1fr)); gap: 16px; }
  .grafico { padding: 18px 20px 12px; border-radius: 12px; background: var(--cartao); }
  .grafico h2 { margin: 0 0 12px; font-size: 15px; }
  .grafico .tela { position: relative; height: 240px; }
  footer { margin-top: 24px; color: var(--apagado); font-size: 12px; text-align: center; }
  code { padding: 1px 6px; border-radius: 4px; background: var(--fundo); }
  @media (max-width: 560px) { .graficos { grid-template-columns: 1fr; } }
</style>
</head>
<body>
<main>
  <header>
    <div class="marca">
      <div class="avatar">A</div>
      <div>
        <h1>AlephBot</h1>
        <p class="sub">${última ? `Última coleta: ${diaEHora(última.quando)}` : 'Painel'}</p>
      </div>
    </div>
    <div class="acoes">
      <span class="selo ${selo.classe}">${selo.texto}</span>
      <nav class="periodo">
        <a href="?periodo=24h" class="${período === '24h' ? 'atual' : ''}">24 h</a>
        <a href="?periodo=7d" class="${período === '7d' ? 'atual' : ''}">7 dias</a>
      </nav>
    </div>
  </header>

  ${aviso ? `<p class="aviso">${aviso}</p>` : ''}

  <section class="cartoes">
    ${cartões.map(c => `
    <div class="cartao">
      <div class="titulo">${c.título}</div>
      <div class="valor">${c.valor}</div>
      <div class="variacao ${c.tendência}">${c.variação}</div>
    </div>`).join('')}
  </section>

  <section class="graficos" id="graficos"></section>

  <footer>Coleta a cada 15 minutos · a página se atualiza sozinha a cada 5</footer>
</main>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script>
<script>
  const { rótulos, gráficos } = ${dados};

  Chart.defaults.color = '#949ba4';
  Chart.defaults.borderColor = 'rgba(255, 255, 255, .06)';
  Chart.defaults.font.family = '"gg sans", "Segoe UI", system-ui, sans-serif';

  // o preenchimento some aos poucos de cima pra baixo
  const degradê = cor => contexto => {
    const { ctx, chartArea } = contexto.chart;
    if (!chartArea) return cor + '33';
    const g = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
    g.addColorStop(0, cor + '59');
    g.addColorStop(1, cor + '00');
    return g;
  };

  const lugar = document.getElementById('graficos');

  for (const g of gráficos) {
    const bloco = document.createElement('div');
    bloco.className = 'grafico';
    bloco.innerHTML = '<h2></h2><div class="tela"><canvas></canvas></div>';
    bloco.querySelector('h2').textContent = g.título;
    lugar.appendChild(bloco);

    new Chart(bloco.querySelector('canvas'), {
      type: 'line',
      data: {
        labels: rótulos,
        datasets: g.séries.map(s => ({
          label: s.nome,
          data: s.valores,
          borderColor: s.cor,
          backgroundColor: degradê(s.cor),
          fill: true,
          borderWidth: 2,
          pointRadius: 0,
          pointHoverRadius: 4,
          tension: g.degrau ? 0 : 0.35,
          stepped: g.degrau ? 'before' : false,
        })),
      },
      options: {
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: { position: 'bottom', labels: { usePointStyle: true, pointStyle: 'circle', boxWidth: 8, padding: 16 } },
          tooltip: { backgroundColor: '#111214', padding: 10, cornerRadius: 8, usePointStyle: true },
        },
        scales: {
          x: { grid: { display: false }, ticks: { maxTicksLimit: 6, maxRotation: 0 } },
          y: { beginAtZero: true, grace: '10%', ticks: { precision: g.inteiros ? 0 : undefined } },
        },
      },
    });
  }
</script>
</body>
</html>`;

return [{ json: { html } }];
